package com.fluxisai.audit;
import java.util.UUID; import com.fluxisai.common.security.CurrentUser; import com.fluxisai.common.web.PageResponse; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuditEventService { private final AuditEventRepository events; private final CurrentUser currentUser; public AuditEventService(AuditEventRepository e,CurrentUser u){events=e;currentUser=u;} @Transactional public void record(String eventType,String entityType,UUID entityId,String action,String details){events.save(new AuditEvent(currentUser.id(),eventType,entityType,entityId,action,details));} @Transactional(readOnly=true) public PageResponse<AuditEventResponse> list(Pageable p){return PageResponse.from(events.findAllByUserId(currentUser.id(),p).map(AuditEventResponse::from));} }
